using EnterpriseERP.Domain.Exceptions;
using EnterpriseERP.Application.Common.Interfaces.Repositories; using EnterpriseERP.Application.Features.PurchaseInvoices.DTOs; using EnterpriseERP.Domain.Entities.Purchasing; using MediatR;  namespace EnterpriseERP.Application.Features.PurchaseInvoices.Queries.GetPurchaseInvoiceById;  public record GetPurchaseInvoiceByIdQuery(Guid Id) : IRequest<PurchaseInvoiceDto>;  public class GetPurchaseInvoiceByIdQueryHandler : IRequestHandler<GetPurchaseInvoiceByIdQuery, PurchaseInvoiceDto> {     private readonly IUnitOfWork _unitOfWork;      public GetPurchaseInvoiceByIdQueryHandler(IUnitOfWork unitOfWork)     {         _unitOfWork = unitOfWork;     }      public async Task<PurchaseInvoiceDto> Handle(GetPurchaseInvoiceByIdQuery request, CancellationToken cancellationToken)     {         var invoice = await _unitOfWork.Repository<PurchaseInvoice>().GetByIdAsync(request.Id);                  if (invoice == null)             throw new PurchasingDomainException($"Purchase invoice with id {request.Id} not found");          var lines = await _unitOfWork.Repository<PurchaseInvoiceLine>().FindAsync(x => x.PurchaseInvoiceId == request.Id);          return new PurchaseInvoiceDto         {             Id = invoice.Id,             InvoiceNumber = invoice.InvoiceNumber,             SupplierInvoiceNumber = invoice.SupplierInvoiceNumber,             InvoiceDate = invoice.InvoiceDate,             SupplierId = invoice.SupplierId,             BranchId = invoice.BranchId,             WarehouseId = invoice.WarehouseId,             SubTotal = invoice.SubTotal,             DiscountAmount = invoice.DiscountAmount,             TaxAmount = invoice.TaxAmount,             TotalAmount = invoice.TotalAmount,             PaidAmount = invoice.PaidAmount,             RemainingAmount = invoice.RemainingAmount,             Status = invoice.Status.ToString(),             Notes = invoice.Notes,             Lines = lines.Select(l => new PurchaseInvoiceLineDto             {                 Id = l.Id,                 ItemId = l.ItemId,                 Quantity = l.Quantity,                 UnitCost = l.UnitCost,                 DiscountPercent = l.DiscountPercent,                 DiscountAmount = l.DiscountAmount,                 TaxPercent = l.TaxPercent,                 TaxAmount = l.TaxAmount,                 LineTotal = l.LineTotal             }).ToList()         };     } }

